import java.util.Arrays;
import java.util.Comparator;

final class KruskalMST {
    public static int kruskalsMST(int V, int[][] edges) {
        validateVertexCount(V);
        Edge[] sortedEdges = toEdges(edges);
        Arrays.sort(sortedEdges, Comparator.comparingInt(edge -> edge.weight));

        DisjointSet disjointSet = new DisjointSet(V);
        int totalWeight = 0;
        int edgesUsed = 0;

        for (Edge edge : sortedEdges) {
            validateVertexId(edge.from, V);
            validateVertexId(edge.to, V);
            if (disjointSet.union(edge.from, edge.to)) {
                totalWeight += edge.weight;
                if (++edgesUsed == V - 1) {
                    break;
                }
            }
        }
        return totalWeight;
    }

    public static void main(String[] args) {
        int[][] edges = {
            {0, 1, 10}, {1, 3, 15}, {2, 3, 4}, {2, 0, 6}, {0, 3, 5}
        };

        System.out.println(kruskalsMST(4, edges));
    }

    private static void validateVertexCount(int vertexCount) {
        if (vertexCount < 0) {
            throw new IllegalArgumentException("vertexCount must be non-negative");
        }
    }

    private static void validateVertexId(int vertexId, int vertexCount) {
        if (vertexId < 0 || vertexId >= vertexCount) {
            throw new IllegalArgumentException(
                "vertex id " + vertexId + " is outside the valid range [0, " + (vertexCount - 1) + "]"
            );
        }
    }

    private static Edge[] toEdges(int[][] edges) {
        if (edges == null) {
            throw new IllegalArgumentException("edges must not be null");
        }

        Edge[] converted = new Edge[edges.length];
        for (int i = 0; i < edges.length; i++) {
            int[] edge = edges[i];
            if (edge == null || edge.length != 3) {
                throw new IllegalArgumentException("edge " + i + " must contain exactly three integers");
            }
            converted[i] = new Edge(edge[0], edge[1], edge[2]);
        }
        return converted;
    }

    private static final class Edge {
        private final int from;
        private final int to;
        private final int weight;

        private Edge(int from, int to, int weight) {
            this.from = from;
            this.to = to;
            this.weight = weight;
        }
    }
}

final class DisjointSet {
    private final int[] parent;
    private final int[] rank;

    public DisjointSet(int n) {
        parent = new int[n];
        rank = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 1;
        }
    }

    public int find(int i) {
        if (parent[i] != i) {
            parent[i] = find(parent[i]);
        }
        return parent[i];
    }

    public boolean union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY) {
            return false;
        }

        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
        return true;
    }
}

